questionvariables.text:
qstem:3+rand(2);

if qstem=3 then (
    /* Choose frequencies for the lower stems. */
    n0:2+rand(3),
    n1:5+rand(3),
    n2:11+rand(3),

    /* The first part of the 30s ends at observation 30. */
    n3a:30-n0-n1-n2,

    /* Distribute the final 10 observations across the upper end. */
    n3b:1+rand(3),
    n5:1+rand(3),
    n4:10-n3b-n5,

    /* Split the 30s somewhere between leaf 6 and leaf 8. */
    split:6+rand(3),

    list0:sort(makelist(rand(10),i,1,n0)),
    list1:sort(makelist(rand(10),i,1,n1)),
    list2:sort(makelist(rand(10),i,1,n2)),
    list3a:sort(makelist(rand(split+1),i,1,n3a)),
    list3b:sort(makelist(split+1+rand(9-split),i,1,n3b)),
    list4:sort(makelist(rand(10),i,1,n4)),

    /* Scores in the 50s stem must be exactly 50. */
    list5:makelist(0,i,1,n5),

    list3:append(list3a,list3b),

    final_list:append(
        list0,
        map(lambda([x],10+x),list1),
        map(lambda([x],20+x),list2),
        map(lambda([x],30+x),list3),
        map(lambda([x],40+x),list4),
        map(lambda([x],50+x),list5)
    )
)
else (
    /* Choose frequencies for the lower stems. */
    n0:2+rand(2),
    n1:4+rand(2),
    n2:10+rand(3),

    /* Put 27 to 29 observations below the 40s. */
    npre:27+rand(3),
    n3:npre-n0-n1-n2,

    /* The first part of the 40s ends at observation 30. */
    n4a:30-npre,

    /* Distribute the remaining observations across the upper 40s and 50. */
    n5:1+rand(3),
    n4b:10-n5,

    /* Split the 40s somewhere between leaf 1 and leaf 3. */
    split:1+rand(3),

    list0:sort(makelist(rand(10),i,1,n0)),
    list1:sort(makelist(rand(10),i,1,n1)),
    list2:sort(makelist(rand(10),i,1,n2)),
    list3:sort(makelist(rand(10),i,1,n3)),
    list4a:sort(makelist(rand(split+1),i,1,n4a)),
    list4b:sort(makelist(split+1+rand(9-split),i,1,n4b)),

    /* Scores in the 50s stem must be exactly 50. */
    list5:makelist(0,i,1,n5),

    list4:append(list4a,list4b),

    final_list:append(
        list0,
        map(lambda([x],10+x),list1),
        map(lambda([x],20+x),list2),
        map(lambda([x],30+x),list3),
        map(lambda([x],40+x),list4),
        map(lambda([x],50+x),list5)
    )
);

ta:(final_list[30]+final_list[31])/2;

/* Display variables. */
pad20(L):=append(L,makelist("",i,1,20-length(L)));

row0:pad20(list0);
row1:pad20(list1);
row2:pad20(list2);
row3:pad20(list3);
row4:pad20(list4);
row5:pad20(list5);

/* Display Q3 as an integer or decimal as appropriate. */
ta_disp:if integerp(ta) then ta else float(ta);
